"""Frozen evaluation. Do not edit this file or layout.py while hill-climbing.

Two held-out sets, built from fixed seeds:
    val:  used to compare runs during the hill-climb.
    test: different grid sizes and seeds, run once at the end. Picking the best
          of many runs on val overfits val a little; test catches that.

Each set has three splits:
    interp: grid sizes and cheese sizes inside the training range, but sizes never trained on.
    extrap: bigger grids and bigger cheeses than anything in training.
    damage: interp layouts with 25% of the mass squares wiped at a quarter of the way through.

The score is the hard metric, never the loss: did all ring squares hold more
than TAU mass, and how early. Rollout length, firing probability and TAU are
fixed here so a training config can't make the test easier.
"""

import numpy as np
import torch

from beebot.ca import first_eaten_step, rollout
from beebot.layout import sample_batch

TAU = 0.5
FIRE_PROB = 0.75
STEPS_PER_CELL = 2  # rollout length is STEPS_PER_CELL * grid size
SMELL_LENGTH = 8.0
LAYOUTS_PER_SIZE = 32
DAMAGE_FRACTION = 0.25

SETS = {
    "val": {
        "seed": 1000,
        "interp": {"sizes": (22, 30, 36), "cheese": (1, 9)},
        "extrap": {"sizes": (48, 64), "cheese": (10, 16)},
    },
    "test": {
        "seed": 2000,
        "interp": {"sizes": (18, 26, 34), "cheese": (1, 9)},
        "extrap": {"sizes": (56, 72), "cheese": (10, 16)},
    },
}


def build_split(seed, sizes, cheese_range):
    """One batch per grid size, with the start distance spanning the whole grid."""
    rng = np.random.default_rng(seed)
    batches = []
    for size in sizes:
        batches.append(sample_batch(rng, size, cheese_range, (2, size // 2), LAYOUTS_PER_SIZE, SMELL_LENGTH))
    return batches


def score_batches(policy, batches, device, seed, damage):
    torch.manual_seed(seed)
    successes, time_scores, final_surrounds = [], [], []
    for batch in batches:
        batch = batch.to(device)
        n_steps = STEPS_PER_CELL * batch.mass.shape[-1]
        damage_step = n_steps // 4 if damage else None
        with torch.no_grad():
            result = rollout(policy, batch, n_steps, FIRE_PROB, TAU, damage_step=damage_step, damage_fraction=DAMAGE_FRACTION)
        first = first_eaten_step(result).float()
        success = first > 0
        successes.append(success.float())
        # Fraction of the rollout used before eating; a failure counts as the whole rollout.
        time_scores.append(torch.where(success, first / n_steps, torch.ones_like(first)))
        final_surrounds.append(result.surround[-1])

    return {
        "success": torch.cat(successes).mean().item(),
        "time": torch.cat(time_scores).mean().item(),
        "final_surround": torch.cat(final_surrounds).mean().item(),
    }


def evaluate(policy, device, which="val"):
    """Scores per split, plus "score": the mean time over splits (lower is better, 1 = never eats)."""
    spec = SETS[which]
    interp = build_split(spec["seed"], **_split_args(spec["interp"]))
    extrap = build_split(spec["seed"] + 1, **_split_args(spec["extrap"]))
    results = {
        "interp": score_batches(policy, interp, device, spec["seed"], damage=False),
        "extrap": score_batches(policy, extrap, device, spec["seed"], damage=False),
        "damage": score_batches(policy, interp, device, spec["seed"] + 2, damage=True),
    }
    results["score"] = float(np.mean([results[name]["time"] for name in ("interp", "extrap", "damage")]))
    return results


def _split_args(split):
    return {"sizes": split["sizes"], "cheese_range": split["cheese"]}
